mapper.select:
SELECT r.*, u.username AS user_name, u.real_name AS user_real_name, u.college AS user_college, u.class_name AS user_class_name, e.name AS event_name, m.name AS meeting_name, rv.real_name AS reviewer_name FROM t_registration r LEFT JOIN ssms_auth.t_user u ON r.user_id = u.id LEFT JOIN t_event e ON r.event_id = e.id LEFT JOIN t_meeting m ON r.meeting_id = m.id LEFT JOIN ssms_auth.t_user rv ON r.reviewed_by = rv.id WHERE r.deleted = 0
AND r.meeting_id = #{meetingId}
AND r.event_id = #{eventId}
AND r.user_id = #{userId}
AND r.status = #{status}
AND (u.real_name LIKE CONCAT('%', #{keyword}, '%') OR u.username LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY r.create_time DESC

SELECT e.name AS event_name, COUNT(*) AS total, SUM(CASE WHEN r.status = 0 THEN 1 ELSE 0 END) AS pending, SUM(CASE WHEN r.status = 1 THEN 1 ELSE 0 END) AS approved, SUM(CASE WHEN r.status = 2 THEN 1 ELSE 0 END) AS rejected, SUM(CASE WHEN r.status = 3 THEN 1 ELSE 0 END) AS cancelled FROM t_registration r LEFT JOIN t_event e ON r.event_id = e.id WHERE r.deleted = 0
AND r.meeting_id = #{meetingId}
GROUP BY r.event_id, e.name ORDER BY total DESC

SELECT u.college, COUNT(*) AS total, COUNT(DISTINCT r.user_id) AS athlete_count, COUNT(DISTINCT r.event_id) AS event_count FROM t_registration r LEFT JOIN ssms_auth.t_user u ON r.user_id = u.id WHERE r.deleted = 0 AND r.status = 1
AND r.meeting_id = #{meetingId}
GROUP BY u.college ORDER BY total DESC
